import { useEffect, useRef } from 'react';
import * as d3 from 'd3';
import { Box } from '@mui/material';

const PALETTE = ['#E69F00', '#56B4E9', '#009E73', '#F0E442', '#0072B2', '#D55E00', '#CC79A7', '#000000'];

export function BarChart({ labels, values, height = 280 }) {
  const ref = useRef(null);
  useEffect(() => {
    const node = ref.current;
    if (!node) return undefined;
    const width = node.clientWidth || 640;
    const margin = { top: 12, right: 12, bottom: 64, left: 64 };
    const innerW = Math.max(120, width - margin.left - margin.right);
    const innerH = height - margin.top - margin.bottom;
    const svg = d3.select(node).select('svg');
    svg.selectAll('*').remove();
    svg.attr('viewBox', `0 0 ${width} ${height}`);
    const root = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);
    const x = d3.scaleBand().domain(labels).range([0, innerW]).padding(0.25);
    const y = d3.scaleLinear().domain([0, d3.max(values) || 1]).nice().range([innerH, 0]);
    root.append('g').attr('transform', `translate(0,${innerH})`).call(d3.axisBottom(x))
      .selectAll('text').attr('transform', 'rotate(-28)').style('text-anchor', 'end');
    root.append('g').call(d3.axisLeft(y).ticks(5).tickFormat(d3.format('~s')));
    root.selectAll('rect').data(labels).join('rect')
      .attr('x', (label) => x(label))
      .attr('y', (_, index) => y(values[index] || 0))
      .attr('width', x.bandwidth())
      .attr('height', (_, index) => innerH - y(values[index] || 0))
      .attr('fill', (_, index) => PALETTE[index % PALETTE.length]);
    return undefined;
  }, [labels, values, height]);
  return (
    <Box ref={ref} sx={{ width: '100%' }}>
      <svg role="img" style={{ width: '100%', height }} />
    </Box>
  );
}

export function LineChart({ series, height = 280 }) {
  const ref = useRef(null);
  useEffect(() => {
    const node = ref.current;
    if (!node) return undefined;
    const width = node.clientWidth || 640;
    const margin = { top: 12, right: 16, bottom: 36, left: 64 };
    const innerW = Math.max(120, width - margin.left - margin.right);
    const innerH = height - margin.top - margin.bottom;
    const labels = series[0] ? series[0].points.map((point) => point.x) : [];
    const svg = d3.select(node).select('svg');
    svg.selectAll('*').remove();
    svg.attr('viewBox', `0 0 ${width} ${height}`);
    const root = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);
    const x = d3.scalePoint().domain(labels).range([0, innerW]);
    const yMax = d3.max(series.flatMap((item) => item.points.map((point) => point.y))) || 1;
    const y = d3.scaleLinear().domain([0, yMax]).nice().range([innerH, 0]);
    const line = d3.line().x((point) => x(point.x)).y((point) => y(point.y));
    root.append('g').attr('transform', `translate(0,${innerH})`).call(d3.axisBottom(x).tickValues(labels.filter((_, index) => index % Math.ceil(labels.length / 8) === 0)));
    root.append('g').call(d3.axisLeft(y).ticks(5).tickFormat(d3.format('~s')));
    series.forEach((item, index) => {
      root.append('path')
        .datum(item.points)
        .attr('fill', 'none')
        .attr('stroke', item.color || PALETTE[index % PALETTE.length])
        .attr('stroke-width', 2.4)
        .attr('d', line);
    });
    const legend = svg.append('g').attr('transform', `translate(${margin.left},8)`);
    series.forEach((item, index) => {
      const group = legend.append('g').attr('transform', `translate(${index * 110},0)`);
      group.append('rect').attr('width', 12).attr('height', 8).attr('fill', item.color || PALETTE[index % PALETTE.length]);
      group.append('text').attr('x', 16).attr('y', 8).attr('font-size', 11).text(item.name);
    });
    return undefined;
  }, [series, height]);
  return (
    <Box ref={ref} sx={{ width: '100%' }}>
      <svg role="img" style={{ width: '100%', height }} />
    </Box>
  );
}
